**C# .NET Implementation:**

```csharp
// .NET implementation using IDistributedCache
public class TenantAwareDistributedCache : IDistributedCache
{
    private readonly IDistributedCache _innerCache;
    private readonly ITenantContext _tenantContext;
    private readonly ILogger<TenantAwareDistributedCache> _logger;

    public TenantAwareDistributedCache(
        IDistributedCache innerCache,
        ITenantContext tenantContext,
        ILogger<TenantAwareDistributedCache> logger)
    {
        _innerCache = innerCache;
        _tenantContext = tenantContext;
        _logger = logger;
    }

    public byte[] Get(string key)
    {
        string tenantKey = BuildTenantAwareKey(key);
        _logger.LogDebug("Cache GET: {TenantKey}", tenantKey);

        var value = _innerCache.Get(tenantKey);

        // Audit log for PHI access
        AuditCacheAccess("GET", tenantKey, value != null);

        return value;
    }

    public Task<byte[]> GetAsync(string key, CancellationToken token = default)
    {
        string tenantKey = BuildTenantAwareKey(key);
        _logger.LogDebug("Cache GET (async): {TenantKey}", tenantKey);

        var task = _innerCache.GetAsync(tenantKey, token);

        // Audit log asynchronously
        task.ContinueWith(t => AuditCacheAccess("GET", tenantKey, t.Result != null), token);

        return task;
    }

    public void Set(string key, byte[] value, DistributedCacheEntryOptions options)
    {
        string tenantKey = BuildTenantAwareKey(key);

        // Apply tenant-specific TTL from configuration
        var tenantConfig = _tenantContext.GetCacheConfiguration();
        if (options.AbsoluteExpirationRelativeToNow == null)
        {
            options.AbsoluteExpirationRelativeToNow = TimeSpan.FromSeconds(tenantConfig.TtlSeconds);
        }

        _logger.LogDebug("Cache SET: {TenantKey}, TTL: {TTL}s",
            tenantKey, options.AbsoluteExpirationRelativeToNow?.TotalSeconds);

        _innerCache.Set(tenantKey, value, options);

        // Audit log
        AuditCacheAccess("SET", tenantKey, true);
    }

    private string BuildTenantAwareKey(string key)
    {
        string tenantId = _tenantContext.GetCurrentTenantId();
        if (string.IsNullOrEmpty(tenantId))
        {
            throw new InvalidOperationException("Tenant context not available");
        }

        // Tenant prefix already included? (defensive check)
        if (key.StartsWith($"{tenantId}:"))
        {
            return key;
        }

        return $"{tenantId}:{key}";
    }

    private void AuditCacheAccess(string operation, string key, bool success)
    {
        _logger.LogInformation(
            "Cache Audit: Tenant={TenantId}, User={UserId}, Operation={Operation}, " +
            "Key={Key}, Success={Success}, Timestamp={Timestamp}",
            _tenantContext.GetCurrentTenantId(),
            _tenantContext.GetCurrentUserId(),
            operation,
            key,
            success,
            DateTime.UtcNow);
    }
}

// Register in Startup.cs
services.AddStackExchangeRedisCache(options =>
{
    options.Configuration = Configuration.GetConnectionString("Redis");
});
services.Decorate<IDistributedCache, TenantAwareDistributedCache>();
