// Node.js implementation using cache-manager
const cacheManager = require('cache-manager');
const redisStore = require('cache-manager-redis-store');
const { getTenantContext } = require('./middleware/tenantContext');
const { auditLog } = require('./services/auditLogger');

class TenantAwareCacheManager {
    constructor(redisClient, config) {
        this.redisClient = redisClient;
        this.config = config;
    }

    async get(key) {
        const tenantId = getTenantContext();
        if (!tenantId) {
            throw new Error('Tenant context not available');
        }

        const tenantKey = `${tenantId}:${key}`;
        const value = await this.redisClient.get(tenantKey);

        // Audit log
        auditLog({
            operation: 'CACHE_GET',
            tenantId,
            key: tenantKey,
            hit: value !== null,
            timestamp: new Date()
        });

        return value;
    }

    async set(key, value, options = {}) {
        const tenantId = getTenantContext();
        if (!tenantId) {
            throw new Error('Tenant context not available');
        }

        const tenantKey = `${tenantId}:${key}`;

        // Get tenant-specific TTL from config
        const tenantConfig = await this.getTenantCacheConfig(tenantId);
        const ttl = options.ttl || tenantConfig.ttlSeconds;

        await this.redisClient.set(tenantKey, value, { ttl });

        // Audit log
        auditLog({
            operation: 'CACHE_SET',
            tenantId,
            key: tenantKey,
            ttl,
            timestamp: new Date()
        });
    }

    async del(key) {
        const tenantId = getTenantContext();
        if (!tenantId) {
            throw new Error('Tenant context not available');
        }

        const tenantKey = `${tenantId}:${key}`;
        await this.redisClient.del(tenantKey);

        // Audit log
        auditLog({
            operation: 'CACHE_DELETE',
            tenantId,
            key: tenantKey,
            timestamp: new Date()
        });
    }

    async getTenantCacheConfig(tenantId) {
        // Load from database or config service
        const config = await configService.getTenantCacheConfig(tenantId);
        return config;
    }
}

module.exports = TenantAwareCacheManager;
