**Task 3.2: Implement Cache Value Encryption**

Add encryption layer for PHI cached in Redis:

```java
@Component
public class EncryptedCacheValueSerializer implements RedisSerializer<Object> {

    @Autowired
    private TenantCacheConfigService configService;

    @Autowired
    private AzureKeyVaultClient keyVaultClient;

    @Override
    public byte[] serialize(Object value) throws SerializationException {
        if (value == null) {
            return new byte[0];
        }

        String tenantId = TenantContext.getCurrentTenantId();
        TenantCacheConfig config = configService.getConfig(tenantId);

        if (!config.isEncryptionEnabled()) {
            // No encryption for non-PHI data (if explicitly disabled)
            return serializeToJson(value).getBytes(StandardCharsets.UTF_8);
        }

        // Serialize to JSON
        String json = serializeToJson(value);

        // Encrypt using tenant-specific DEK from Key Vault
        String dekUrl = config.getEncryptionKeyVaultUrl();
        byte[] encryptedData = keyVaultClient.encrypt(dekUrl, json.getBytes());

        return encryptedData;
    }

    @Override
    public Object deserialize(byte[] bytes) throws SerializationException {
        if (bytes == null || bytes.length == 0) {
            return null;
        }

        String tenantId = TenantContext.getCurrentTenantId();
        TenantCacheConfig config = configService.getConfig(tenantId);

        if (!config.isEncryptionEnabled()) {
            // No decryption needed
            String json = new String(bytes, StandardCharsets.UTF_8);
            return deserializeFromJson(json);
        }

        // Decrypt using tenant-specific DEK
        String dekUrl = config.getEncryptionKeyVaultUrl();
        byte[] decryptedData = keyVaultClient.decrypt(dekUrl, bytes);

        String json = new String(decryptedData, StandardCharsets.UTF_8);
        return deserializeFromJson(json);
    }

    private String serializeToJson(Object value) {
        ObjectMapper mapper = new ObjectMapper();
        try {
            return mapper.writeValueAsString(value);
        } catch (JsonProcessingException e) {
            throw new SerializationException("Failed to serialize to JSON", e);
        }
    }

    private Object deserializeFromJson(String json) {
        ObjectMapper mapper = new ObjectMapper();
        try {
            return mapper.readValue(json, Object.class);
        } catch (JsonProcessingException e) {
            throw new SerializationException("Failed to deserialize from JSON", e);
        }
    }
}
