**Week 4: Cache Invalidation Infrastructure**

**Task 4.1: Implement Event-Driven Invalidation**

Set up Azure Service Bus topic for cache invalidation events:

```java
// Event publisher (triggered on database updates)
@Service
public class CacheInvalidationEventPublisher {

    @Autowired
    private ServiceBusSenderClient serviceBusClient;

    public void publishInvalidationEvent(String tenantId, String resourceType, String resourceId) {
        CacheInvalidationEvent event = new CacheInvalidationEvent();
        event.setTenantId(tenantId);
        event.setResourceType(resourceType);
        event.setResourceId(resourceId);
        event.setTimestamp(Instant.now());

        ServiceBusMessage message = new ServiceBusMessage(
            new ObjectMapper().writeValueAsString(event)
        );
        message.setMessageId(UUID.randomUUID().toString());
        message.setContentType("application/json");

        serviceBusClient.sendMessage(message);

        log.info("Published cache invalidation event: tenant={}, type={}, id={}",
            tenantId, resourceType, resourceId);
    }
}

// Event subscriber (in cache service)
@Service
public class CacheInvalidationEventSubscriber {

    @Autowired
    private RedisCacheManager cacheManager;

    @ServiceBusListener(
        destination = "cache-invalidation",
        containerFactory = "serviceBusListenerContainerFactory"
    )
    public void handleInvalidationEvent(CacheInvalidationEvent event) {
        String tenantId = event.getTenantId();
        String resourceType = event.getResourceType();
        String resourceId = event.getResourceId();

        // Delete specific cache entry
        String cacheKey = String.format("%s:%s:%s", tenantId, resourceType, resourceId);
        cacheManager.getCache("main").evict(cacheKey);

        // Delete related cache entries (e.g., search results containing this resource)
        String pattern = String.format("%s:%s:*:%s", tenantId, resourceType, resourceId);
        deleteKeysByPattern(pattern);

        log.info("Processed cache invalidation: tenant={}, key={}", tenantId, cacheKey);
    }

    private void deleteKeysByPattern(String pattern) {
        // Use SCAN instead of KEYS for production (non-blocking)
        RedisConnection connection = cacheManager.getConnectionFactory().getConnection();
        try {
            ScanOptions options = ScanOptions.scanOptions().match(pattern).count(100).build();
            Cursor<byte[]> cursor = connection.scan(options);

            while (cursor.hasNext()) {
                byte[] key = cursor.next();
                connection.del(key);
            }
        } finally {
            connection.close();
        }
    }
}

// Usage in service layer
@Service
public class BeneficiaryService {

    @Autowired
    private BeneficiaryRepository repository;

    @Autowired
    private CacheInvalidationEventPublisher invalidationPublisher;

    @Transactional
    public Beneficiary updateBeneficiary(Long beneficiaryId, BeneficiaryUpdate update) {
        Beneficiary beneficiary = repository.findById(beneficiaryId)
            .orElseThrow(() -> new NotFoundException("Beneficiary not found"));

        beneficiary.apply(update);
        repository.save(beneficiary);

        // Publish cache invalidation event
        String tenantId = TenantContext.getCurrentTenantId();
        invalidationPublisher.publishInvalidationEvent(tenantId, "beneficiary", beneficiaryId.toString());

        return beneficiary;
    }
}
