@SpringBootTest
@Testcontainers
public class TenantAwareCacheTest {

    @Container
    static GenericContainer<?> redis = new GenericContainer<>("redis:6.2-alpine")
        .withExposedPorts(6379);

    @Autowired
    private TenantAwareCacheManager cacheManager;

    @Test
    public void testTenantIsolation_differentTenantsSameKey_shouldReturnDifferentValues() {
        // Arrange
        String cacheKey = "beneficiary:123456";
        Beneficiary txBeneficiary = new Beneficiary("John Doe", "TX");
        Beneficiary caBeneficiary = new Beneficiary("Jane Smith", "CA");

        // Act: Cache data for Texas tenant
        TenantContext.setCurrentTenantId("TX");
        cacheManager.put(cacheKey, txBeneficiary);

        // Act: Cache different data for California tenant
        TenantContext.setCurrentTenantId("CA");
        cacheManager.put(cacheKey, caBeneficiary);

        // Assert: Each tenant retrieves their own data
        TenantContext.setCurrentTenantId("TX");
        Beneficiary retrievedTx = cacheManager.get(cacheKey, Beneficiary.class);
        assertEquals("John Doe", retrievedTx.getName());
        assertEquals("TX", retrievedTx.getState());

        TenantContext.setCurrentTenantId("CA");
        Beneficiary retrievedCa = cacheManager.get(cacheKey, Beneficiary.class);
        assertEquals("Jane Smith", retrievedCa.getName());
        assertEquals("CA", retrievedCa.getState());
    }

    @Test
    public void testCacheKeyFormat_shouldIncludeTenantPrefix() {
        // Arrange
        TenantContext.setCurrentTenantId("TX");
        String cacheKey = "beneficiary:123456";

        // Act
        cacheManager.put(cacheKey, new Beneficiary("John Doe", "TX"));

        // Assert: Verify actual Redis key includes tenant prefix
        RedisConnection connection = cacheManager.getConnectionFactory().getConnection();
        Set<byte[]> keys = connection.keys("TX:beneficiary:*".getBytes());
        assertEquals(1, keys.size());

        String actualKey = new String(keys.iterator().next());
        assertTrue(actualKey.startsWith("TX:"));
    }

    @Test
    public void testMissingTenantContext_shouldThrowException() {
        // Arrange: Clear tenant context
        TenantContext.clear();

        // Act & Assert
        assertThrows(IllegalStateException.class, () -> {
            cacheManager.get("beneficiary:123456", Beneficiary.class);
        });
    }
}
