@SpringBootTest
@DirtiesContext
public class CacheInvalidationIntegrationTest {

    @Autowired
    private BeneficiaryService beneficiaryService;

    @Autowired
    private RedisCacheManager cacheManager;

    @Test
    public void testCacheInvalidation_updateBeneficiary_shouldInvalidateCache() throws InterruptedException {
        // Arrange
        TenantContext.setCurrentTenantId("TX");
        Long beneficiaryId = 123456L;

        // Warm cache by reading beneficiary
        Beneficiary original = beneficiaryService.getBeneficiary(beneficiaryId);
        assertEquals("Original Name", original.getName());

        // Verify cache hit (2nd read should come from cache)
        long startTime = System.currentTimeMillis();
        Beneficiary cached = beneficiaryService.getBeneficiary(beneficiaryId);
        long duration = System.currentTimeMillis() - startTime;
        assertTrue(duration < 10, "Cache hit should be <10ms");

        // Act: Update beneficiary (should trigger cache invalidation)
        BeneficiaryUpdate update = new BeneficiaryUpdate();
        update.setName("Updated Name");
        beneficiaryService.updateBeneficiary(beneficiaryId, update);

        // Wait for async invalidation event processing
        Thread.sleep(500);

        // Assert: Next read should fetch fresh data from database (cache miss)
        Beneficiary refreshed = beneficiaryService.getBeneficiary(beneficiaryId);
        assertEquals("Updated Name", refreshed.getName());

        // Verify cache was actually cleared
        Cache cache = cacheManager.getCache("beneficiaries");
        String cacheKey = "TX:BeneficiaryService:getBeneficiary:" + beneficiaryId;
        Cache.ValueWrapper wrapper = cache.get(cacheKey);
        assertNotNull(wrapper); // Cache should be repopulated after refresh
    }
}
