### Example 2: Pennsylvania Provider Directory Caching

**Business Context:**
Pennsylvania Medicaid manages 87,000 enrolled providers (physicians, dentists, hospitals, pharmacies). The Provider Directory API serves:

- Provider search by specialty, location, network (Managed Care Organizations)
- Provider detail pages (demographics, credentials, practice locations)
- Provider eligibility to submit claims (active enrollment status)

Provider data is relatively static (updated weekly), making it ideal for aggressive caching. Without caching, provider search queries join 12 database tables and take 1.5-4 seconds.

**Caching Strategy:**
- **Cache Isolation Model:** Logical Partitioning (Tier 2 - Medium Tenant)
- **Cache Infrastructure:** Shared Azure Redis cluster, Pennsylvania uses Redis Database 0
- **Cache TTL:** 60 minutes (provider data changes infrequently)
- **Encryption:** AES-256-GCM with Pennsylvania-specific DEK

**Implementation:**

```csharp
// .NET implementation with IDistributedCache
public class ProviderService
{
    private readonly IDistributedCache _cache;
    private readonly ProviderRepository _repository;
    private readonly ITenantContext _tenantContext;
    private readonly ILogger<ProviderService> _logger;

    public ProviderService(
        IDistributedCache cache,
        ProviderRepository repository,
        ITenantContext tenantContext,
        ILogger<ProviderService> logger)
    {
        _cache = cache;
        _repository = repository;
        _tenantContext = tenantContext;
        _logger = logger;
    }

    /// <summary>
    /// Search providers by specialty with tenant-aware caching
    /// Cache key format: PA:provider:search:specialty:{specialty}:page:{page}
    /// </summary>
    public async Task<ProviderSearchResult> SearchBySpecialty(
        string specialty,
        int page,
        int pageSize)
    {
        string cacheKey = $"provider:search:specialty:{specialty}:page:{page}";

        // Try cache first (middleware adds "PA:" prefix)
        string cachedJson = await _cache.GetStringAsync(cacheKey);
        if (cachedJson != null)
        {
            _logger.LogDebug("Cache HIT: {CacheKey}", cacheKey);
            return JsonSerializer.Deserialize<ProviderSearchResult>(cachedJson);
        }

        // Cache miss - query database
        _logger.LogInformation("Cache MISS: {CacheKey} - Querying database", cacheKey);
        var result = await _repository.SearchBySpecialty(specialty, page, pageSize);

        // Cache result with 60-minute TTL
        var cacheOptions = new DistributedCacheEntryOptions
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(60)
        };

        string resultJson = JsonSerializer.Serialize(result);
        await _cache.SetStringAsync(cacheKey, resultJson, cacheOptions);

        return result;
    }

    /// <summary>
    /// Update provider credentials - invalidates cached searches
    /// </summary>
    public async Task UpdateProviderCredentials(long providerId, CredentialUpdate update)
    {
        var provider = await _repository.GetById(providerId);
        if (provider == null)
        {
            throw new NotFoundException($"Provider {providerId} not found");
        }

        provider.ApplyCredentialUpdate(update);
        await _repository.SaveAsync(provider);

        // Invalidate cached provider detail
        string detailCacheKey = $"provider:detail:{providerId}";
        await _cache.RemoveAsync(detailCacheKey);

        // Invalidate all specialty searches that might include this provider
        // (Tag-based invalidation using Redis Sets)
        await InvalidateProviderSearches(providerId, provider.Specialties);

        _logger.LogInformation(
            "Invalidated cache for provider {ProviderId}: detail and {SpecialtyCount} specialty searches",
            providerId, provider.Specialties.Count);
    }

    private async Task InvalidateProviderSearches(long providerId, List<string> specialties)
    {
        var redis = _cache.GetConnection();
        string tenantId = _tenantContext.GetCurrentTenantId();

        foreach (var specialty in specialties)
        {
            // Get all search result cache keys for this specialty
            string tagKey = $"{tenantId}:provider:search:tag:specialty:{specialty}";
            var cacheKeys = await redis.SetMembersAsync(tagKey);

            // Delete all search result cache entries
            foreach (var cacheKey in cacheKeys)
            {
                await redis.KeyDeleteAsync(cacheKey);
            }

            _logger.LogDebug(
                "Invalidated {Count} search result caches for specialty {Specialty}",
                cacheKeys.Length, specialty);
        }
    }
}
