**Cache Warming Strategy:**

Pennsylvania runs a nightly cache warming job to pre-populate frequently accessed provider searches:

```csharp
// Scheduled background job - runs daily at 2 AM
public class ProviderCacheWarmingJob : IHostedService
{
    private readonly IServiceProvider _serviceProvider;
    private readonly ILogger<ProviderCacheWarmingJob> _logger;

    public ProviderCacheWarmingJob(
        IServiceProvider serviceProvider,
        ILogger<ProviderCacheWarmingJob> logger)
    {
        _serviceProvider = serviceProvider;
        _logger = logger;
    }

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        // Run daily at 2 AM Eastern Time
        var timer = new PeriodicTimer(TimeSpan.FromHours(24));

        while (await timer.WaitForNextTickAsync(cancellationToken))
        {
            await WarmProviderCache();
        }
    }

    private async Task WarmProviderCache()
    {
        using var scope = _serviceProvider.CreateScope();
        var providerService = scope.ServiceProvider.GetRequiredService<ProviderService>();
        var tenantContext = scope.ServiceProvider.GetRequiredService<ITenantContext>();

        // Set tenant context to Pennsylvania
        tenantContext.SetCurrentTenantId("PA");

        _logger.LogInformation("Starting provider cache warming for Pennsylvania...");

        // Top 20 specialties by search volume
        var topSpecialties = new[] {
            "Family Practice", "Internal Medicine", "Pediatrics", "Cardiology",
            "Orthopedic Surgery", "Obstetrics & Gynecology", "Psychiatry",
            "General Surgery", "Emergency Medicine", "Anesthesiology",
            "Radiology", "Dermatology", "Ophthalmology", "Urology",
            "Neurology", "Gastroenterology", "Nephrology", "Oncology",
            "Endocrinology", "Pulmonology"
        };

        int warmedCount = 0;
        foreach (var specialty in topSpecialties)
        {
            // Warm first 5 pages for each specialty
            for (int page = 1; page <= 5; page++)
            {
                await providerService.SearchBySpecialty(specialty, page, pageSize: 20);
                warmedCount++;
            }
        }

        _logger.LogInformation(
            "Completed provider cache warming: {Count} searches pre-cached",
            warmedCount);
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}
