### Example 3: Multi-State FHIR Patient Access API

**Business Context:**
Gainwell operates FHIR Patient Access APIs for 15 state Medicaid agencies to comply with CMS Interoperability Final Rule. Beneficiaries use mobile apps to access their health records (claims, medications, lab results, immunizations) via FHIR R4 API.

**Challenge:**
- Each state is a separate tenant with distinct PHI
- FHIR resources must be cached for performance (<1-second response time requirement)
- Beneficiary may have records across multiple states (moved from Pennsylvania to Ohio)
- Must prevent cross-state PHI leakage via cache

**Caching Strategy:**
- **Cache Isolation Model:** Namespace Isolation (Tier 3 - Small States)
- **Cache Infrastructure:** Shared Redis cluster with tenant-prefixed keys
- **Cache TTL:** 30 minutes for FHIR resources
- **Encryption:** Mandatory AES-256-GCM (FHIR contains detailed PHI)

**Implementation:**

```javascript
// Node.js implementation with cache-manager
const cacheManager = require('cache-manager');
const redisStore = require('cache-manager-redis-store');
const { getTenantContext } = require('./middleware/tenantContext');

class FHIRResourceCache {
    constructor(redisClient) {
        this.redis = redisClient;
    }

    /**
     * Cache FHIR Patient resource
     * Cache key format: PA:fhir:Patient:123456
     */
    async cachePatient(patientId, patientResource) {
        const tenantId = getTenantContext();
        const cacheKey = `fhir:Patient:${patientId}`;

        // Validate tenant ownership
        if (patientResource.identifier.system !== `http://medicaid.${tenantId}.gov/beneficiary-id`) {
            throw new Error('Cache poisoning attempt: Patient resource tenant mismatch');
        }

        // Encrypt FHIR resource before caching
        const encrypted = await this.encryptPHI(tenantId, patientResource);

        // Cache with 30-minute TTL (middleware adds "PA:" prefix)
        await this.redis.set(cacheKey, encrypted, { ttl: 1800 });

        console.log(`Cached FHIR Patient resource: tenant=${tenantId}, patient=${patientId}`);
    }

    /**
     * Retrieve cached FHIR Patient resource
     */
    async getPatient(patientId) {
        const tenantId = getTenantContext();
        const cacheKey = `fhir:Patient:${patientId}`;

        const encrypted = await this.redis.get(cacheKey);
        if (!encrypted) {
            console.log(`Cache MISS: ${cacheKey}`);
            return null;
        }

        // Decrypt FHIR resource
        const patientResource = await this.decryptPHI(tenantId, encrypted);

        // Audit log for PHI access
        await this.auditFHIRAccess(tenantId, 'Patient', patientId, 'CACHE_HIT');

        console.log(`Cache HIT: ${cacheKey}`);
        return patientResource;
    }

    /**
     * Cache FHIR ExplanationOfBenefit (claim) resources
     * Cache key format: PA:fhir:ExplanationOfBenefit:search:patient:123456:page:1
     */
    async cacheEOBSearch(patientId, page, eobBundle) {
        const tenantId = getTenantContext();
        const cacheKey = `fhir:ExplanationOfBenefit:search:patient:${patientId}:page:${page}`;

        // Validate all resources belong to this tenant
        for (const entry of eobBundle.entry) {
            const eob = entry.resource;
            if (!this.validateTenantOwnership(tenantId, eob.patient.reference)) {
                throw new Error('Cache poisoning: EOB bundle contains cross-tenant data');
            }
        }

        const encrypted = await this.encryptPHI(tenantId, eobBundle);
        await this.redis.set(cacheKey, encrypted, { ttl: 1800 });

        console.log(`Cached FHIR EOB search: tenant=${tenantId}, patient=${patientId}, page=${page}`);
    }

    /**
     * Invalidate all cached FHIR resources for a patient
     */
    async invalidatePatientResources(patientId) {
        const tenantId = getTenantContext();

        // Invalidate Patient resource
        await this.redis.del(`fhir:Patient:${patientId}`);

        // Invalidate all ExplanationOfBenefit searches for this patient
        const eobPattern = `${tenantId}:fhir:ExplanationOfBenefit:search:patient:${patientId}:*`;
        await this.deleteKeysByPattern(eobPattern);

        // Invalidate MedicationRequest, Immunization, Observation, etc.
        const resourceTypes = ['MedicationRequest', 'Immunization', 'Observation', 'DiagnosticReport'];
        for (const resourceType of resourceTypes) {
            const pattern = `${tenantId}:fhir:${resourceType}:search:patient:${patientId}:*`;
            await this.deleteKeysByPattern(pattern);
        }

        console.log(`Invalidated all FHIR resources for tenant=${tenantId}, patient=${patientId}`);
    }

    async encryptPHI(tenantId, data) {
        // Use Azure Key Vault to encrypt with tenant-specific DEK
        const keyVaultUrl = await this.getTenantEncryptionKey(tenantId);
        const encrypted = await azureKeyVault.encrypt(keyVaultUrl, JSON.stringify(data));
        return encrypted;
    }

    async decryptPHI(tenantId, encrypted) {
        const keyVaultUrl = await this.getTenantEncryptionKey(tenantId);
        const decrypted = await azureKeyVault.decrypt(keyVaultUrl, encrypted);
        return JSON.parse(decrypted);
    }

    validateTenantOwnership(tenantId, patientReference) {
        // FHIR reference format: Patient/123456
        const patientId = patientReference.split('/')[1];
        // Check if patient belongs to this tenant (query database or validate identifier)
        // Return true if valid, false if cross-tenant reference detected
        return true; // Simplified for example
    }

    async deleteKeysByPattern(pattern) {
        // Use SCAN instead of KEYS (non-blocking)
        let cursor = '0';
        do {
            const result = await this.redis.scan(cursor, 'MATCH', pattern, 'COUNT', 100);
            cursor = result[0];
            const keys = result[1];

            if (keys.length > 0) {
                await this.redis.del(...keys);
            }
        } while (cursor !== '0');
    }

    async auditFHIRAccess(tenantId, resourceType, resourceId, operation) {
        const auditEvent = {
            timestamp: new Date().toISOString(),
            tenantId,
            resourceType,
            resourceId,
            operation,
            userId: getTenantContext().userId,
            sourceIp: getTenantContext().sourceIp
        };

        await auditLogger.log('FHIR_CACHE_ACCESS', auditEvent);
    }
}

module.exports = FHIRResourceCache;
